import AppKit

/// Watches a pasteboard for new text copies. macOS has no change notification,
/// so this polls `changeCount` (an integer read, effectively free) twice a second.
@MainActor
public final class PasteboardWatcher {
    /// Types that password managers and other apps set to say "don't record this".
    /// See nspasteboard.org.
    public static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    private let pasteboard: NSPasteboard
    private let onCopy: (String, NSRunningApplication?) -> Void
    private var lastChangeCount: Int
    private var timer: Timer?
    /// Change count of a write we made ourselves (picking an entry), to skip echoing it.
    private var ownWriteChangeCount: Int?

    public init(pasteboard: NSPasteboard = .general, onCopy: @escaping (String, NSRunningApplication?) -> Void) {
        self.pasteboard = pasteboard
        self.onCopy = onCopy
        self.lastChangeCount = pasteboard.changeCount
    }

    public func start(interval: TimeInterval = 0.5) {
        guard timer == nil else { return }
        let timer = Timer(timeInterval: interval, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.check() }
        }
        timer.tolerance = interval / 2 // let macOS coalesce wakeups
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    public func stop() {
        timer?.invalidate()
        timer = nil
    }

    /// Reads the pasteboard if it changed. Public so tests can drive it without a timer.
    public func check() {
        let count = pasteboard.changeCount
        guard count != lastChangeCount else { return }
        lastChangeCount = count
        if count == ownWriteChangeCount { return }
        guard let text = Self.recordableText(from: pasteboard) else { return }
        onCopy(text, NSWorkspace.shared.frontmostApplication)
    }

    /// Puts `text` on the pasteboard without recording it as a new copy.
    public func write(_ text: String) {
        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)
        ownWriteChangeCount = pasteboard.changeCount
        lastChangeCount = pasteboard.changeCount
    }

    /// Plain text from the pasteboard, or nil if it's concealed/transient or not text.
    public static func recordableText(from pasteboard: NSPasteboard) -> String? {
        let types = Set((pasteboard.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: ignoredTypes) else { return nil }
        return pasteboard.string(forType: .string)
    }
}
